 1  import { useState } from 'react';
 2  import {
 3    Badge,
 4    Button,
 5    List,
 6    ListItem,
 7    ListItemIcon,
 8    ListItemText,
 9    Paper,
10    Typography,
11  } from '@mui/material';
12  import NotificationsIcon from '@mui/icons-material/Notifications';
13  import MailIcon from '@mui/icons-material/Mail';
14  
15  export interface Notice {
16    id: number;
17    text: string;
18    read: boolean;
19  }
20  
21  const NOTICES: Notice[] = [
22    { id: 1, text: 'Alan Turing joined your workspace', read: false },
23    { id: 2, text: 'Your export is ready', read: false },
24    { id: 3, text: 'Weekly digest sent', read: true },
25    { id: 4, text: 'Grace Hopper changed her role', read: false },
26  ];
27  
28  export function Notifications({ initial = NOTICES }: { initial?: Notice[] }) {
29    const [notices, setNotices] = useState(initial);
30    const unread = notices.filter((n) => !n.read).length;
31  
32    return (
33      <Paper component="section" aria-labelledby="notifications-title">
34        <Typography id="notifications-title" variant="h6" component="h1">
35          <Badge badgeContent={unread} color="secondary">
36            <NotificationsIcon aria-hidden />
37          </Badge>{' '}
38          Notifications
39          <Typography variant="srOnly" component="span">
40            {unread === 0 ? 'No unread notifications' : `${unread} unread notifications`}
41          </Typography>
42        </Typography>
43        <List dense>
44          {notices.map((n) => (
45            <ListItem key={n.id} selected={!n.read}>
46              <ListItemIcon>
47                <MailIcon color={n.read ? 'disabled' : 'primary'} />
48              </ListItemIcon>
49              <ListItemText primary={n.text} secondary={n.read ? 'Read' : 'Unread'} />
50            </ListItem>
51          ))}
52        </List>
53        <Button
54          disabled={unread === 0}
55          onClick={() => setNotices(notices.map((n) => ({ ...n, read: true })))}
56        >
57          Mark all as read
58        </Button>
59      </Paper>
60    );
61  }
